from textual.app import App, ComposeResult
from textual.widgets import Button, Static, Label
from textual.message import Message

class CustomWidget(Static):
    """A widget with a button that sends custom messages to its parent."""

    class ButtonClicked(Message):
        """Custom message sent when the button is clicked."""
        def __init__(self, button_label: str) -> None:
            self.button_label = button_label
            super().__init__()

    def compose(self) -> ComposeResult:
        yield Button("Click me", id="my_button")

    def on_button_pressed(self, event: Button.Pressed) -> None:
        """Send custom message to parent when button is pressed."""
        self.post_message(self.ButtonClicked("Button was clicked!"))

class MainApp(App):
    """Main application that handles messages from CustomWidget."""

    CSS = """
    Screen {
        layout: vertical;
    }
    """

    def compose(self) -> ComposeResult:
        yield Label("Status: No message yet", id="status_label")
        yield CustomWidget(id="custom_widget")

    def on_custom_widget_button_clicked(self, message: CustomWidget.ButtonClicked) -> None:
        """Handle the custom message from CustomWidget."""
        status = self.query_one("#status_label", Label)
        status.update(f"Status: {message.button_label}")

if __name__ == "__main__":
    MainApp().run()

